from pathlib import Path
import csv,json,html
ROOT=Path(__file__).resolve().parents[2]
claims=list(csv.DictReader((ROOT/'data/claims.csv').open(encoding='utf-8', newline='')))
deps=list(csv.DictReader((ROOT/'data/dependencies.csv').open(encoding='utf-8', newline='')))
lit=list(csv.DictReader((ROOT/'data/literature.csv').open(encoding='utf-8', newline='')))
arts=list(csv.DictReader((ROOT/'data/artifacts.csv').open(encoding='utf-8', newline='')))
layer_for_status={'PROVED_LEAN_KERNEL':'Formal proofs','DEFINITION':'Object','PROVED_SYMBOLIC':'Theorems','PROVED_SYMBOLIC_PLUS_CERTIFICATE':'Theorems','EXACT_CERTIFICATE':'Certificates','PROVED_SYMBOLIC_PLUS_CRT':'Counterexample','PROVED_SHARP':'Threshold','NOT_CLAIMED':'Boundary','CONDITIONAL_HISTORICAL_CENSUS_BOUND':'Boundary'}
nodes=[]
for c in claims:
    nodes.append({'id':c['claim_id'],'label':c['claim_id'],'title':c['claim'],'kind':'claim','layer':layer_for_status.get(c['status'],'Claims'),'status':c['status'],'artifact':c['primary_evidence'],'scope':c['scope']})
for a in arts:
    nodes.append({'id':a['artifact_id'],'label':a['artifact_id'],'title':a['title'],'kind':'artifact','layer':'Evidence','status':'ARTIFACT','artifact':a['path'],'scope':'evidence'})
for r in lit:
    if r['decision'] in {'ADD','CITE','CONTEXT'}:
        nodes.append({'id':'L_'+r['key'],'label':r['authors'].split(';')[0].split(',')[0]+' '+r['year'],'title':r['title'],'kind':'literature','layer':'Literature','status':r['decision'],'artifact':r['identifier'],'scope':r['affinity']})
edges=[{'source':e['source'],'target':e['target'],'relation':e['relation']} for e in deps]
for a in arts:
    if a['supports_claims']!='all':
        for cid in a['supports_claims'].split(';'):
            if cid: edges.append({'source':a['artifact_id'],'target':cid,'relation':'supports'})
for r in lit:
    if r['decision'] in {'ADD','CITE','CONTEXT'}: edges.append({'source':'L_'+r['key'],'target':'C001','relation':'contextualizes'})
graph={'meta':{'title':'Primitive Radix–Möbius Dynamics — Epistemic Graph','version':'RC3.3','generated_from':['data/claims.csv','data/dependencies.csv','data/artifacts.csv','data/literature.csv']},'nodes':nodes,'edges':edges}
outj=ROOT/'outputs/interactive/epistemic_graph.json'; outj.parent.mkdir(parents=True,exist_ok=True); outj.write_text(json.dumps(graph,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
layers=['Formal proofs','Object','Theorems','Rigidity','Certificates','Counterexample','Threshold','Evidence','Literature','Boundary','Claims']
html_doc=r"""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Primitive Radix–Möbius Dynamics — Epistemic Graph</title><style>
:root{--bg:#fafbfe;--panel:#f0f3fa;--ink:#17365e;--muted:#526984;--line:#b3c4da;--accent:#5282b6;--ok:#5282b6;--cert:#ad8bcd;--counter:#8c80b8;--boundary:#ba8cae;--lit:#7a94c7}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui;background:var(--bg);color:var(--ink)}header{padding:18px 22px;border-bottom:1px solid var(--line);display:flex;gap:16px;align-items:center;flex-wrap:wrap}h1{font-size:18px;margin:0}input,select{background:var(--panel);border:1px solid var(--line);color:var(--ink);padding:9px 11px;border-radius:9px}.wrap{display:grid;grid-template-columns:minmax(0,1fr) 340px;height:calc(100vh - 70px)}#stage{overflow:auto;position:relative}.inspector{border-left:1px solid var(--line);padding:18px;background:var(--panel);overflow:auto}.inspector h2{font-size:17px}.chip{display:inline-block;padding:3px 8px;border:1px solid var(--line);border-radius:999px;font-size:11px;margin:2px}.layer{fill:#eef2fa;stroke:#c0cce0;rx:16}.layerTitle{fill:#526984;font-size:12px}.edge{stroke:#a0b1cc;stroke-width:1.3;fill:none;opacity:.55}.edge.supports{stroke:#5282b6}.edge.refutes{stroke:#ba8cae}.node{cursor:pointer}.node rect{fill:#ffffff;stroke:#a0b1cc;stroke-width:1.2}.node text{fill:#17365e;font-size:11px}.node.claim.proved rect{stroke:#5282b6}.node.certificate rect{stroke:#ad8bcd}.node.literature rect{stroke:#7a94c7}.node.boundary rect{stroke:#ba8cae}.node.counterexample rect{stroke:#8c80b8}.dim{opacity:.12}.hot rect{stroke-width:3;filter:drop-shadow(0 0 5px #5282b6)}a{color:var(--accent)}pre{white-space:pre-wrap;color:#526984}.legend{font-size:12px;color:var(--muted)}@media(max-width:900px){.wrap{grid-template-columns:1fr;height:auto}.inspector{border-left:0;border-top:1px solid var(--line);min-height:280px}}
</style></head><body><header><h1>Primitive Radix–Möbius Dynamics · Epistemic Graph</h1><input id="q" placeholder="Search claim, theorem, source…"><select id="kind"><option value="all">All nodes</option><option>claim</option><option>artifact</option><option>literature</option></select><span class="legend">click node · dependency/evidence highlighting · self-contained</span></header><div class="wrap"><div id="stage"><svg id="svg"></svg></div><aside class="inspector"><h2 id="ititle">Select a node</h2><div id="ichips"></div><p id="ibody">Claims, exact certificates, software artifacts and literature are separate node types.</p><pre id="ipath"></pre></aside></div><script>
const G=__GRAPH__; const layers=__LAYERS__; const W=layers.length*160+30, colW=160, nodeW=142,nodeH=52,gap=14,top=54; const byId=Object.fromEntries(G.nodes.map(n=>[n.id,n])); const L={}; layers.forEach((l,i)=>L[l]={x:20+i*colW,nodes:G.nodes.filter(n=>n.layer===l)}); const maxN=Math.max(...layers.map(l=>L[l].nodes.length)); const H=Math.max(760,top+maxN*(nodeH+gap)+70); const svg=document.getElementById('svg'); svg.setAttribute('viewBox',`0 0 ${W} ${H}`); svg.setAttribute('width',W);svg.setAttribute('height',H); const pos={};
function el(t,a={}){const e=document.createElementNS('http://www.w3.org/2000/svg',t);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);return e} layers.forEach((l,i)=>{const g=el('g'); const r=el('rect',{x:L[l].x-8,y:15,width:colW-12,height:H-30,class:'layer'});g.appendChild(r); const tx=el('text',{x:L[l].x,y:38,class:'layerTitle'});tx.textContent=l;g.appendChild(tx); L[l].nodes.forEach((n,j)=>pos[n.id]={x:L[l].x,y:top+j*(nodeH+gap)});svg.appendChild(g)});
G.edges.forEach(e=>{if(!pos[e.source]||!pos[e.target])return; const a=pos[e.source],b=pos[e.target]; const p=el('path',{d:`M ${a.x+nodeW} ${a.y+nodeH/2} C ${(a.x+b.x+nodeW)/2} ${a.y+nodeH/2}, ${(a.x+b.x+nodeW)/2} ${b.y+nodeH/2}, ${b.x} ${b.y+nodeH/2}`,class:'edge '+e.relation,'data-source':e.source,'data-target':e.target});svg.appendChild(p)});
G.nodes.forEach(n=>{const p=pos[n.id];const g=el('g',{class:`node ${n.kind} ${n.status.includes('PROVED')?'proved':''} ${n.status==='EXACT_CERTIFICATE'?'certificate':''} ${n.status==='NOT_CLAIMED'?'boundary':''} ${n.status.includes('CRT')?'counterexample':''}`,'data-id':n.id});const r=el('rect',{x:p.x,y:p.y,width:nodeW,height:nodeH,rx:9});g.appendChild(r);const t1=el('text',{x:p.x+8,y:p.y+18});t1.textContent=n.label;g.appendChild(t1);const t2=el('text',{x:p.x+8,y:p.y+36});t2.textContent=n.title.slice(0,19)+(n.title.length>19?'…':'');g.appendChild(t2);g.addEventListener('click',()=>select(n.id));svg.appendChild(g)});
function select(id){document.querySelectorAll('.node,.edge').forEach(x=>x.classList.add('dim'));const ids=new Set([id]);G.edges.filter(e=>e.source===id||e.target===id).forEach(e=>{ids.add(e.source);ids.add(e.target)});ids.forEach(i=>document.querySelector(`[data-id="${i}"]`)?.classList.remove('dim'));document.querySelectorAll(`.edge[data-source="${id}"],.edge[data-target="${id}"]`).forEach(x=>x.classList.remove('dim'));document.querySelector(`[data-id="${id}"]`)?.classList.add('hot');const n=byId[id];document.getElementById('ititle').textContent=n.title;document.getElementById('ichips').innerHTML=`<span class=chip>${n.kind}</span><span class=chip>${n.status}</span><span class=chip>${n.layer}</span>`;document.getElementById('ibody').textContent=`${n.scope||''}`;document.getElementById('ipath').textContent=n.artifact||''}
function filter(){const q=document.getElementById('q').value.toLowerCase(),k=document.getElementById('kind').value;G.nodes.forEach(n=>{const ok=(k==='all'||n.kind===k)&&(!q||(n.title+' '+n.label+' '+n.status).toLowerCase().includes(q));document.querySelector(`[data-id="${n.id}"]`).style.display=ok?'':'none'})}document.getElementById('q').addEventListener('input',filter);document.getElementById('kind').addEventListener('change',filter);
</script></body></html>""".replace('__GRAPH__',json.dumps(graph,ensure_ascii=False)).replace('__LAYERS__',json.dumps(layers))
outh=ROOT/'outputs/interactive/epistemic_graph.html'; outh.write_text(html_doc,encoding='utf-8'); print(outj);print(outh)
